import { useEffect, useMemo, useState } from "react";
import { Link, useLocation, useRoute } from "wouter";
import { Activity, ArrowDownRight, ArrowLeft, ArrowUpRight, Bot, Check, ChevronRight, Clock3, CreditCard, Database, Download, Filter, GitBranch, Layers3, LockKeyhole, Play, RefreshCw, Search, ShieldAlert, Sparkles, Target, Timer, TrendingUp, UserRound, WalletCards, X, Zap } from "lucide-react";
import { AppShell, EmptyState, MetricCard, PageIntro, SectionLabel, StatusPill } from "@/components/AppShell";
import { NetworkLegend, RevenueNetwork } from "@/components/RevenueNetwork";
import { FailureMixChart, PaymentMethodsChart, ProbabilityChart, RecoveryFunnel, RecoveryTrendChart } from "@/components/Charts";
import { apiMode, executeRecovery, getAnalytics, getAuditEvents, getDashboardMetrics, getDecisions, getTransaction, getTransactions, runBatchRecovery } from "@/lib/api";
import type { AnalyticsSnapshot, AuditEvent, DashboardMetrics, RecoveryDecision, RecoveryRunResult, Transaction, TransactionStatus } from "@/lib/types";
import { cn } from "@/lib/utils";

const money = (value: number) => `₹${value >= 100000 ? `${(value / 100000).toFixed(1)}L` : value >= 1000 ? `${(value / 1000).toFixed(1)}k` : value.toLocaleString("en-IN")}`;
const fullMoney = (value: number) => `₹${value.toLocaleString("en-IN")}`;
const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function LoadingBlock({ lines = 4 }: { lines?: number }) { return <div className="space-y-3 animate-pulse">{Array.from({ length: lines }, (_, index) => <div key={index} className="h-12 rounded-lg bg-white/[0.05]" />)}</div>; }
function ErrorState({ message = "Recovery Engine temporarily unavailable." }: { message?: string }) { return <div className="glass-panel flex min-h-[260px] flex-col items-center justify-center rounded-xl px-6 text-center"><ShieldAlert className="mb-3 h-7 w-7 text-[#F0B36B]" /><div className="font-display text-[15px] text-[#E7F4F7]">{message}</div><p className="mt-2 text-[12px] text-[#78919B]">Showing demo-safe context while the service reconnects.</p><button className="btn-signal mt-5 rounded-lg border border-[#6DE7F2]/20 bg-[#6DE7F2]/[0.08] px-4 py-2 font-mono text-[10px] tracking-[.12em] text-[#6DE7F2]">USE DEMO MODE</button></div>; }
function ToneForStatus(status: TransactionStatus): "success" | "warning" | "danger" | "info" { return status === "recovered" ? "success" : status === "blocked" ? "danger" : status === "human_review" || status === "pending" ? "warning" : "info"; }
function StatusLabel({ status }: { status: TransactionStatus }) { const labels: Record<TransactionStatus, string> = { recovered: "Recovered", pending: "Pending", human_review: "Human review", blocked: "Blocked", at_risk: "At risk" }; return <StatusPill label={labels[status]} tone={ToneForStatus(status)} />; }
function ActionLabel({ action }: { action: Transaction["aiAction"] }) { return <span className="font-mono text-[10px] uppercase tracking-[.08em] text-[#BBD1D5]">{action === "retry" ? "Retry" : action === "payment_link" ? "Payment link" : action === "escalate" ? "Escalate" : "No action"}</span>; }

export function DashboardPage() {
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null); const [error, setError] = useState(false); const [selectedNode, setSelectedNode] = useState<string | null>(null); const [, navigate] = useLocation();
  useEffect(() => { getDashboardMetrics().then(setMetrics).catch(() => setError(true)); }, []);
  const m = metrics || { revenueProcessed: 0, revenueAtRisk: 0, revenueRecovered: 0, recoveryRate: 0, automatedRecoveries: 0, humanEscalations: 0, processedDelta: 0, atRiskDelta: 0, recoveredDelta: 0, rateDelta: 0 };
  return <AppShell title="Revenue Recovery Command Center" eyebrow="OVERVIEW" action={<Link href="/recovery" className="btn-signal hidden items-center gap-2 rounded-lg border border-[#6DE7F2]/25 bg-[#6DE7F2]/[0.08] px-3 py-2 font-mono text-[10px] tracking-[.1em] text-[#6DE7F2] sm:flex"><Play className="h-3.5 w-3.5" />RUN RECOVERY</Link>}>
    <div className="mb-7 flex flex-wrap items-center justify-between gap-3"><div><div className="font-mono text-[10px] tracking-[.18em] text-[#6DE7F2]">LIVE OPERATIONS / 09:42:18 IST</div><h2 className="mt-2 font-display text-[27px] font-medium tracking-[-.04em] text-[#F0FBFC] sm:text-[34px]">Revenue is moving in the right direction.</h2><p className="mt-2 text-[13px] text-[#7F98A2]">Autonomous interventions are protecting merchant revenue across the payment graph.</p></div><div className="flex items-center gap-2"><StatusPill label={apiMode} tone="info" /><span className="font-mono text-[9px] text-[#607782]">SYNCED 14s AGO</span></div></div>
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_minmax(320px,.75fr)]"><div className="glass-panel relative min-h-[440px] overflow-hidden rounded-2xl p-5 sm:p-7"><div className="absolute left-6 top-6 z-10"><SectionLabel action={<span className="font-mono text-[9px] text-[#6C858E]">LIVE NETWORK / 3D</span>}>REVENUE FLOW</SectionLabel><h3 className="font-display text-[19px] text-[#E7F4F7]">The recovery engine is actively intervening.</h3><p className="mt-2 max-w-sm text-[12px] leading-5 text-[#7B949D]">Watch transactions move from failure to governed recovery across the merchant graph.</p></div><RevenueNetwork className="absolute inset-0 rounded-none border-0" compact onSelect={(node) => { setSelectedNode(node.label); if (node.id === "risk") navigate("/transactions/TXN_9283"); }} /><div className="absolute bottom-6 left-6 z-10"><NetworkLegend /></div>{selectedNode && <div className="absolute right-5 top-5 z-10 rounded-lg border border-[#6DE7F2]/20 bg-[#08151e]/90 px-3 py-2 font-mono text-[10px] text-[#6DE7F2]">FOCUS · {selectedNode}</div>}</div><div className="grid grid-cols-2 gap-3 content-start">{[["REVENUE PROCESSED", money(m.revenueProcessed), `${m.processedDelta}%`, "#8295FF"], ["REVENUE AT RISK", money(m.revenueAtRisk), `${m.atRiskDelta}%`, "#F0B36B"], ["RECOVERED", money(m.revenueRecovered), `${m.recoveredDelta}%`, "#81E6A8"], ["RECOVERY RATE", `${m.recoveryRate}%`, `+${m.rateDelta}%`, "#6DE7F2"]].map(([label, value, delta, color]) => <div key={label} className="panel-soft rounded-xl p-4"><div className="font-mono text-[9px] tracking-[.12em] text-[#728A94]">{label}</div><div className="mt-4 font-display text-[24px] font-semibold tracking-[-.04em] text-[#F0FBFC]">{metrics ? value : "—"}</div><div className="mt-2 flex items-center gap-1.5 font-mono text-[10px]" style={{ color }}><ArrowUpRight className="h-3 w-3" />{delta}<span className="text-[#607782]">30d</span></div><div className="mt-4 h-1 overflow-hidden rounded-full bg-white/[0.06]"><div className="h-full rounded-full" style={{ width: `${label === "RECOVERY RATE" ? m.recoveryRate : Math.min(100, Number(String(value).replace(/[^0-9.]/g, "")) / (label === "REVENUE PROCESSED" ? 18400 : label === "REVENUE AT RISK" ? 3200 : 2100) * 100)}%`, background: color }} /></div></div>)}</div></div>
    {error ? <div className="mt-5"><ErrorState /></div> : <>
      <div className="mt-8"><SectionLabel action={<span className="font-mono text-[9px] text-[#607782]">LAST 30 DAYS</span>}>PERFORMANCE SIGNALS</SectionLabel><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{metrics ? <><MetricCard label="Revenue processed" value={money(m.revenueProcessed)} delta={`${m.processedDelta}%`} icon={Layers3} tone="signal" data={[.25,.34,.32,.52,.48,.7,.68,.9]} /><MetricCard label="Revenue at risk" value={money(m.revenueAtRisk)} delta={`${m.atRiskDelta}%`} icon={ShieldAlert} tone="warning" data={[.72,.62,.7,.58,.65,.48,.42,.36]} /><MetricCard label="Revenue recovered" value={money(m.revenueRecovered)} delta={`${m.recoveredDelta}%`} icon={TrendingUp} tone="success" data={[.2,.3,.28,.46,.44,.68,.65,.88]} /><MetricCard label="Recovery rate" value={`${m.recoveryRate}%`} delta={`+${m.rateDelta}%`} icon={Target} tone="signal" data={[.4,.43,.52,.5,.61,.63,.7,.82]} /><MetricCard label="Automated recoveries" value={m.automatedRecoveries.toString()} delta="14.2%" icon={Bot} tone="success" data={[.2,.28,.36,.32,.55,.62,.7,.82]} /><MetricCard label="Human escalations" value={m.humanEscalations.toString()} delta="-8.1%" icon={UserRound} tone="warning" data={[.82,.72,.76,.6,.58,.53,.46,.4]} /></> : <div className="col-span-full"><LoadingBlock lines={2} /></div>}</div></div>
      <div className="mt-8 grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(320px,.65fr)]"><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel action={<div className="flex gap-1"><button className="rounded-md bg-white/[0.07] px-2 py-1 font-mono text-[9px] text-[#E7F4F7]">7D</button><button className="rounded-md px-2 py-1 font-mono text-[9px] text-[#607782] hover:text-[#DDEDEF]">30D</button><button className="rounded-md px-2 py-1 font-mono text-[9px] text-[#607782] hover:text-[#DDEDEF]">90D</button></div>}>REVENUE RECOVERY</SectionLabel><div className="mb-4 flex items-center gap-5 font-mono text-[9px] uppercase tracking-[.1em] text-[#718992]"><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded bg-[#6DE7F2]" />recovered</span><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded bg-[#F0B36B]" />at risk</span></div><RecoveryTrendChart data={[{ label: "Aug 28", risk: 24000, recovered: 16400 }, { label: "Aug 29", risk: 28000, recovered: 19200 }, { label: "Aug 30", risk: 22000, recovered: 17400 }, { label: "Aug 31", risk: 33000, recovered: 22800 }, { label: "Sep 01", risk: 30000, recovered: 21200 }, { label: "Sep 02", risk: 35000, recovered: 24900 }, { label: "Sep 03", risk: 38000, recovered: 26700 }]} /></div><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel>RECOVERY FUNNEL</SectionLabel><p className="mb-5 text-[12px] text-[#6F8791]">Where at-risk value is moving right now.</p><RecoveryFunnel /><div className="mt-5 border-t border-white/[0.08] pt-4 font-mono text-[9px] text-[#667E87]">241 / 1,000 events converted to recovered revenue</div></div></div>
      <div className="mt-8 grid gap-5 xl:grid-cols-[minmax(0,1.15fr)_minmax(340px,.85fr)]"><div className="glass-panel rounded-xl p-5 sm:p-6"><div className="flex items-start justify-between gap-4"><div><SectionLabel>LIVE RECOVERY ENGINE</SectionLabel><p className="text-[12px] text-[#6F8791]">Autonomous interventions across the last 60 seconds.</p></div><span className="flex items-center gap-2 font-mono text-[9px] text-[#81E6A8]"><span className="status-dot success" />STREAMING</span></div><div className="mt-7 flex items-center justify-between gap-1 overflow-x-auto pb-2">{["DETECTED", "ANALYZING", "DECISION", "POLICY CHECK", "EXECUTING", "RECOVERED"].map((stage, index) => <div key={stage} className="flex min-w-[74px] flex-1 items-center"><div className="text-center"><div className={cn("mx-auto grid h-10 w-10 place-items-center rounded-full border font-mono text-[10px]", index === 5 ? "border-[#81E6A8]/40 bg-[#81E6A8]/10 text-[#81E6A8]" : index === 3 ? "border-[#F0B36B]/40 bg-[#F0B36B]/10 text-[#F0B36B]" : "border-[#6DE7F2]/35 bg-[#6DE7F2]/[0.08] text-[#6DE7F2]")}>{index === 5 ? <Check className="h-4 w-4" /> : `0${index + 1}`}</div><div className="mt-3 whitespace-nowrap font-mono text-[8px] tracking-[.08em] text-[#8199A3]">{stage}</div></div>{index < 5 && <div className="mx-1 h-px flex-1 bg-gradient-to-r from-[#6DE7F2]/30 to-[#6DE7F2]/[0.04]" />}</div>)}</div><div className="mt-7 grid grid-cols-3 gap-3"><div className="rounded-lg bg-white/[0.035] p-3"><div className="font-mono text-[9px] text-[#607782]">IN FLIGHT</div><div className="mt-2 font-display text-xl text-[#E7F4F7]">18</div></div><div className="rounded-lg bg-white/[0.035] p-3"><div className="font-mono text-[9px] text-[#607782]">RECOVERED</div><div className="mt-2 font-display text-xl text-[#81E6A8]">₹4,500</div></div><div className="rounded-lg bg-white/[0.035] p-3"><div className="font-mono text-[9px] text-[#607782]">AVG LATENCY</div><div className="mt-2 font-display text-xl text-[#E7F4F7]">1.8s</div></div></div></div><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel action={<Link href="/ai-decisions" className="font-mono text-[9px] text-[#6DE7F2]">VIEW ALL <ChevronRight className="inline h-3 w-3" /></Link>}>AI RECOVERY INTELLIGENCE</SectionLabel><div className="rounded-lg border border-[#6DE7F2]/15 bg-[#6DE7F2]/[0.035] p-4"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] text-[#6DE7F2]">TXN_9281</div><div className="mt-1 font-display text-lg text-[#E7F4F7]">₹4,500 <span className="ml-1 text-[11px] text-[#78919B]">/ Bank Timeout</span></div></div><span className="font-display text-2xl font-semibold text-[#81E6A8]">91%</span></div><div className="mt-4 flex items-center justify-between border-t border-white/[0.08] pt-3"><span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#718992]">AI RECOMMENDATION</span><span className="font-mono text-[10px] text-[#6DE7F2]">RETRY PAYMENT</span></div><div className="mt-3 flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-[.12em] text-[#718992]">POLICY DECISION</span><StatusPill label="Approved" tone="success" /></div></div><Link href="/transactions/TXN_9281" className="mt-4 flex items-center justify-between border-b border-white/[0.08] pb-3 text-[12px] text-[#A8BEC3] hover:text-white"><span>Inspect structured explanation</span><ChevronRight className="h-4 w-4 text-[#6DE7F2]" /></Link><div className="mt-4 flex items-center gap-2 font-mono text-[9px] text-[#607782]"><LockKeyhole className="h-3.5 w-3.5 text-[#81E6A8]" />No hidden chain-of-thought exposed</div></div></div>
    </>}</AppShell>;
}

export function TransactionsPage() {
  const [items, setItems] = useState<Transaction[] | null>(null); const [query, setQuery] = useState(""); const [filter, setFilter] = useState("All"); const [sort, setSort] = useState("Newest");
  useEffect(() => { getTransactions().then(setItems); }, []);
  const filtered = useMemo(() => (items || []).filter((item) => { const matches = `${item.id} ${item.customer} ${item.failureReason}`.toLowerCase().includes(query.toLowerCase()); const statusMatches = filter === "All" || (filter === "Recoverable" && item.recoveryProbability >= 75) || (filter === "At Risk" && item.status === "at_risk") || (filter === "Recovered" && item.status === "recovered") || (filter === "Escalated" && item.status === "human_review") || (filter === "Blocked" && item.status === "blocked"); return matches && statusMatches; }).sort((a,b) => sort === "Amount" ? b.amount - a.amount : b.timestamp.localeCompare(a.timestamp)), [items, query, filter, sort]);
  return <AppShell title="Transaction Explorer" eyebrow="TRANSACTIONS" action={<button className="btn-signal hidden items-center gap-2 rounded-lg border border-white/10 bg-white/[0.04] px-3 py-2 font-mono text-[10px] text-[#A9C0C5] sm:flex"><Download className="h-3.5 w-3.5" />EXPORT</button>}><PageIntro eyebrow="TRANSACTION LEDGER / 2,481 EVENTS" title="Every payment has a next best action." description="Search failures, inspect recovery probability, and follow the governed path from risk to resolution." action={<Link href="/recovery" className="btn-signal inline-flex items-center gap-2 rounded-lg bg-[#6DE7F2] px-4 py-2.5 font-mono text-[10px] font-semibold tracking-[.1em] text-[#061116]"><Zap className="h-3.5 w-3.5" />RECOVERY CENTER</Link>} /><div className="mb-4 grid gap-3 sm:grid-cols-[minmax(0,1fr)_150px_150px]"><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#627B84]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search transaction, customer, failure..." className="h-10 w-full rounded-lg border border-white/[0.1] bg-white/[0.035] pl-10 pr-3 text-[12px] text-[#E7F4F7] placeholder:text-[#607782] focus:border-[#6DE7F2]/40 focus:outline-none" /></div><div className="relative"><Filter className="absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-[#627B84]" /><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-10 w-full appearance-none rounded-lg border border-white/[0.1] bg-[#0D1D27] pl-9 pr-3 font-mono text-[10px] text-[#B5C8CC] focus:outline-none">{["All", "At Risk", "Recoverable", "Recovered", "Escalated", "Blocked"].map((option) => <option key={option}>{option}</option>)}</select></div><select value={sort} onChange={(event) => setSort(event.target.value)} className="h-10 rounded-lg border border-white/[0.1] bg-[#0D1D27] px-3 font-mono text-[10px] text-[#B5C8CC] focus:outline-none"><option>Newest</option><option>Amount</option></select></div><div className="glass-panel overflow-hidden rounded-xl"><div className="table-scroll overflow-x-auto"><table className="w-full min-w-[980px] border-collapse text-left"><thead><tr className="border-b border-white/[0.08] bg-white/[0.025]">{["Transaction", "Amount", "Customer", "Payment method", "Failure", "Probability", "AI action", "Policy", "Status", ""].map((head) => <th key={head} className="whitespace-nowrap px-4 py-3.5 font-mono text-[9px] font-medium uppercase tracking-[.12em] text-[#607782]">{head}</th>)}</tr></thead><tbody>{items ? filtered.map((item) => <tr key={item.id} className="table-row border-b border-white/[0.06] last:border-0"><td className="px-4 py-4"><Link href={`/transactions/${item.id}`} className="font-mono text-[11px] text-[#6DE7F2] hover:underline">{item.id}</Link><div className="mt-1 font-mono text-[9px] text-[#607782]">{item.timestamp}</div></td><td className="px-4 py-4 font-display text-[13px] text-[#E7F4F7]">{fullMoney(item.amount)}</td><td className="px-4 py-4 text-[12px] text-[#A9BEC3]">{item.customer}</td><td className="px-4 py-4"><span className="inline-flex items-center gap-2 text-[11px] text-[#A9BEC3]"><CreditCard className="h-3.5 w-3.5 text-[#708892]" />{item.paymentMethod}</span></td><td className="px-4 py-4 text-[11px] text-[#A9BEC3]">{item.failureReason}</td><td className="px-4 py-4"><span className={cn("font-display text-[14px] font-semibold", item.recoveryProbability >= 80 ? "text-[#81E6A8]" : item.recoveryProbability >= 60 ? "text-[#F0B36B]" : "text-[#FF8C88]")}>{item.recoveryProbability}%</span></td><td className="px-4 py-4"><ActionLabel action={item.aiAction} /></td><td className="px-4 py-4">{item.policy === "approved" ? <StatusPill label="Approved" tone="success" /> : item.policy === "blocked" ? <StatusPill label="Blocked" tone="danger" /> : <StatusPill label="Pending" tone="warning" />}</td><td className="px-4 py-4"><StatusLabel status={item.status} /></td><td className="px-4 py-4"><Link href={`/transactions/${item.id}`} className="grid h-7 w-7 place-items-center rounded-md text-[#607782] hover:bg-white/[0.07] hover:text-[#E7F4F7]"><ChevronRight className="h-4 w-4" /></Link></td></tr>) : <tr><td colSpan={10} className="p-5"><LoadingBlock lines={6} /></td></tr>}</tbody></table>{items && filtered.length === 0 && <div className="p-6"><EmptyState icon={Search} title="No transactions match this view" text="Adjust the search or state filter to return to the active ledger." /></div>}</div><div className="flex items-center justify-between border-t border-white/[0.08] px-4 py-3 font-mono text-[9px] text-[#607782]"><span>Showing {filtered.length} of {items?.length ?? 0} events</span><span>Page 1 / 12 <ChevronRight className="ml-1 inline h-3 w-3" /></span></div></div></AppShell>;
}

export function TransactionDetailPage() {
  const [, params] = useRoute("/transactions/:id"); const id = (params as any)?.id || "TXN_9281"; const [, navigate] = useLocation(); const [item, setItem] = useState<Transaction | null>(null); const [processing, setProcessing] = useState(false); const [recovered, setRecovered] = useState(false);
  useEffect(() => { getTransaction(id).then(setItem).catch(() => setItem(null)); }, [id]);
  if (!item) return <AppShell title="Transaction Detail" eyebrow="TRANSACTION"><LoadingBlock lines={6} /></AppShell>;
  const approved = item.policy === "approved" && item.status !== "blocked";
  const doRecovery = async () => { setProcessing(true); await executeRecovery(item.id); setProcessing(false); setRecovered(true); };
  return <AppShell title={item.id} eyebrow="TRANSACTION DETAIL"><button onClick={() => navigate("/transactions")} className="mb-5 inline-flex items-center gap-2 font-mono text-[10px] tracking-[.1em] text-[#718992] hover:text-[#E7F4F7]"><ArrowLeft className="h-3.5 w-3.5" />BACK TO TRANSACTIONS</button><div className="mb-8 flex flex-col justify-between gap-4 border-b border-white/[0.08] pb-7 md:flex-row md:items-end"><div><div className="mb-3 flex items-center gap-3"><span className="font-mono text-[10px] tracking-[.18em] text-[#6DE7F2]">{item.id} / LIVE TRACE</span><StatusLabel status={recovered ? "recovered" : item.status} /></div><h2 className="font-display text-[32px] font-medium tracking-[-.05em] text-[#F0FBFC]">{fullMoney(item.amount)} <span className="text-[#6D858E]">· {item.failureReason}</span></h2><p className="mt-2 text-[13px] text-[#8199A3]">{item.customer} · {item.paymentMethod} · {item.timestamp}</p></div><div className="flex items-center gap-2"><div className="rounded-lg border border-white/[0.09] bg-white/[0.025] px-3 py-2 font-mono text-[9px] text-[#718992]">AUDIT TRACE <span className="ml-2 text-[#6DE7F2]">ACTIVE</span></div></div></div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_340px]"><div className="space-y-5"><div className="glass-panel rounded-xl p-5 sm:p-7"><SectionLabel>TRANSACTION OVERVIEW</SectionLabel><div className="grid gap-5 border-b border-white/[0.08] pb-6 sm:grid-cols-3"><div><div className="font-mono text-[9px] text-[#607782]">CUSTOMER</div><div className="mt-2 text-[13px] text-[#D8E9EB]">{item.customer}</div><div className="mt-1 font-mono text-[9px] text-[#607782]">{item.customerHistory}</div></div><div><div className="font-mono text-[9px] text-[#607782]">PAYMENT METHOD</div><div className="mt-2 text-[13px] text-[#D8E9EB]">{item.paymentMethod}</div><div className="mt-1 font-mono text-[9px] text-[#607782]">Attempt {item.retryCount + 1} of 2</div></div><div><div className="font-mono text-[9px] text-[#607782]">FAILURE REASON</div><div className="mt-2 text-[13px] text-[#F0B36B]">{item.failureReason}</div><div className="mt-1 font-mono text-[9px] text-[#607782]">Detected {item.timestamp}</div></div></div><div className="mt-7 flex flex-col gap-7 sm:flex-row sm:items-center"><div className="relative grid h-36 w-36 shrink-0 place-items-center rounded-full" style={{ background: `conic-gradient(#81E6A8 ${item.recoveryProbability * 3.6}deg, rgba(255,255,255,.07) 0deg)` }}><div className="grid h-28 w-28 place-items-center rounded-full bg-[#0D1B25]"><div className="text-center"><div className="font-display text-3xl font-semibold text-[#81E6A8]">{item.recoveryProbability}%</div><div className="font-mono text-[8px] tracking-[.1em] text-[#78919B]">RECOVERY PROBABILITY</div></div></div></div><div><div className="font-mono text-[10px] tracking-[.16em] text-[#6DE7F2]">AI DIAGNOSIS</div><div className="mt-3 font-display text-xl text-[#E7F4F7]">{item.diagnosis}</div><p className="mt-3 max-w-lg text-[12px] leading-5 text-[#79929B]">Signal confidence is built from failure history, amount exposure, payment context, and customer recovery behavior.</p></div></div></div><div className="grid gap-5 md:grid-cols-2"><div className="glass-panel rounded-xl p-5"><SectionLabel>AI RECOMMENDATION</SectionLabel><div className="flex items-center justify-between"><div className="font-display text-xl text-[#6DE7F2]">{item.aiAction === "retry" ? "RETRY PAYMENT" : item.aiAction === "payment_link" ? "CREATE PAYMENT LINK" : "ESCALATE"}</div><Sparkles className="h-5 w-5 text-[#6DE7F2]" /></div><div className="mt-4 border-t border-white/[0.08] pt-4 font-mono text-[10px] text-[#78919B]">Recommended from structured signals. No hidden reasoning is exposed.</div></div><div className="glass-panel rounded-xl p-5"><SectionLabel>POLICY ENGINE</SectionLabel><div className="space-y-3">{[["Recovery probability", item.recoveryProbability > 80], ["Amount within threshold", item.amount < 10000], ["Retry count available", item.retryCount < 2], ["Failure type retryable", !item.failureReason.includes("Limit")]].map(([label, pass]) => <div key={label as string} className="flex items-center justify-between font-mono text-[10px] text-[#9DB2B8]"><span>{label as string}</span>{pass ? <Check className="h-3.5 w-3.5 text-[#81E6A8]" /> : <X className="h-3.5 w-3.5 text-[#FF8C88]" />}</div>)}</div><div className={cn("mt-4 border-t pt-4 font-mono text-[10px] tracking-[.1em]", approved ? "border-[#81E6A8]/20 text-[#81E6A8]" : "border-[#FF8C88]/20 text-[#FF8C88]")}>{approved ? "DECISION · APPROVED" : "DECISION · BLOCKED BY POLICY"}</div></div></div></div><aside className="space-y-5"><div className="glass-panel sticky top-[96px] rounded-xl p-5"><SectionLabel>RECOVERY ACTION</SectionLabel>{recovered ? <div className="rounded-lg border border-[#81E6A8]/20 bg-[#81E6A8]/[0.08] p-4"><div className="flex items-center gap-2 font-mono text-[10px] text-[#81E6A8]"><Check className="h-4 w-4" />RECOVERY COMPLETE</div><div className="mt-3 font-display text-2xl text-[#E7F4F7]">{fullMoney(item.amount)}</div><p className="mt-1 text-[11px] text-[#79929B]">Payment recovered and audit trail updated.</p></div> : <><p className="text-[12px] leading-5 text-[#8099A2]">Execute the approved recovery action. Policy guardrails remain enforced at the moment of execution.</p><button disabled={!approved || processing} onClick={doRecovery} className={cn("btn-signal mt-5 flex w-full items-center justify-center gap-2 rounded-lg px-4 py-3 font-mono text-[10px] font-semibold tracking-[.12em]", approved ? "bg-[#6DE7F2] text-[#061116]" : "cursor-not-allowed bg-white/[0.06] text-[#607782]")}>{processing ? <><RefreshCw className="h-3.5 w-3.5 animate-spin" />PROCESSING...</> : approved ? <><Play className="h-3.5 w-3.5" />EXECUTE RECOVERY</> : <><LockKeyhole className="h-3.5 w-3.5" />BLOCKED BY POLICY</>}</button>{!approved && <div className="mt-3 flex items-start gap-2 rounded-lg border border-[#FF8C88]/15 bg-[#FF8C88]/[0.05] p-3 font-mono text-[9px] leading-4 text-[#FF9B96]"><ShieldAlert className="mt-0.5 h-3.5 w-3.5 shrink-0" />HUMAN REVIEW REQUIRED · Amount exceeds automated recovery threshold.</div>}</>}</div><div className="glass-panel rounded-xl p-5"><SectionLabel>EXECUTION TIMELINE</SectionLabel><div className="space-y-0">{["Failure detected", "AI analyzed", "Policy approved", "Retry initiated", recovered ? "Payment recovered" : "Waiting for action"].map((label, index) => <div key={label} className="flex gap-3"><div className="flex flex-col items-center"><div className={cn("mt-1 h-2 w-2 rounded-full", index === 4 && !recovered ? "bg-[#536C77]" : index === 2 && !approved ? "bg-[#FF8C88]" : "bg-[#6DE7F2]")} />{index < 4 && <div className="h-8 w-px bg-white/[0.1]" />}</div><div className="pb-4 font-mono text-[10px] text-[#9EB2B7]">{label}<div className="mt-1 text-[9px] text-[#607782]">{index < 2 ? `09:41:0${index + 2}` : index === 2 ? "09:41:04" : index === 3 && recovered ? "09:41:05" : index === 4 && recovered ? "09:41:08" : "awaiting approval"}</div></div></div>)}</div></div><div className="glass-panel rounded-xl p-5"><SectionLabel>AUDIT TRAIL</SectionLabel><div className="space-y-3">{["Risk event recorded", "ML prediction stored", "Policy decision logged"].map((event, index) => <div key={event} className="flex items-center gap-3 font-mono text-[10px] text-[#8299A1]"><span className="text-[#607782]">09:41:0{index + 2}</span><span>{event}</span></div>)}<Link href="/audit" className="mt-2 inline-flex items-center gap-1 font-mono text-[9px] text-[#6DE7F2]">OPEN FULL AUDIT <ChevronRight className="h-3 w-3" /></Link></div></div></aside></div></AppShell>;
}

export function RecoveryPage() {
  const [items, setItems] = useState<Transaction[] | null>(null); const [running, setRunning] = useState(false); const [stage, setStage] = useState(0); const [result, setResult] = useState<RecoveryRunResult | null>(null);
  useEffect(() => { getTransactions().then(setItems); }, []);
  const stages = ["SCANNING TRANSACTIONS", "IDENTIFYING REVENUE AT RISK", "PREDICTING RECOVERY PROBABILITY", "GENERATING AI INTERVENTIONS", "APPLYING POLICY GUARDRAILS", "EXECUTING RECOVERY ACTIONS", "UPDATING REVENUE"];
  const run = async () => { setRunning(true); setResult(null); setStage(0); stages.forEach((_, index) => window.setTimeout(() => setStage(index), index * 460)); const data = await runBatchRecovery(); setResult(data); setRunning(false); };
  return <AppShell title="Recovery Center" eyebrow="RECOVERY"><PageIntro eyebrow="AUTONOMOUS ENGINE / DEMO CONTROL" title="Move from revenue at risk to recovered revenue." description="Review governed interventions, then run the autonomous engine across the current recovery queue." action={<button onClick={run} className="btn-signal inline-flex items-center gap-2 rounded-lg bg-[#6DE7F2] px-4 py-2.5 font-mono text-[10px] font-semibold tracking-[.1em] text-[#061116]"><Play className="h-3.5 w-3.5" />RUN AI RECOVERY</button>} /><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><div className="glass-panel rounded-xl p-5"><div className="font-mono text-[9px] text-[#607782]">RECOVERY QUEUE</div><div className="mt-3 font-display text-3xl text-[#E7F4F7]">1,000</div><div className="mt-2 font-mono text-[10px] text-[#F0B36B]">327 revenue-risk events</div></div><div className="glass-panel rounded-xl p-5"><div className="font-mono text-[9px] text-[#607782]">APPROVED ACTIONS</div><div className="mt-3 font-display text-3xl text-[#81E6A8]">241</div><div className="mt-2 font-mono text-[10px] text-[#81E6A8]">Within guardrails</div></div><div className="glass-panel rounded-xl p-5"><div className="font-mono text-[9px] text-[#607782]">HUMAN ESCALATIONS</div><div className="mt-3 font-display text-3xl text-[#F0B36B]">53</div><div className="mt-2 font-mono text-[10px] text-[#F0B36B]">Needs merchant review</div></div><div className="glass-panel rounded-xl p-5"><div className="font-mono text-[9px] text-[#607782]">VALUE RECOVERED</div><div className="mt-3 font-display text-3xl text-[#6DE7F2]">₹3.42L</div><div className="mt-2 font-mono text-[10px] text-[#6DE7F2]">67.4% recovery rate</div></div></div><div className="mt-8 grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel action={<StatusPill label="Policy guarded" tone="success" />}>RECOVERY QUEUE</SectionLabel><div className="table-scroll overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b border-white/[0.08]"><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">TRANSACTION</th><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">VALUE</th><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">PROBABILITY</th><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">ACTION</th><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">POLICY</th><th className="py-3 font-mono text-[9px] tracking-[.12em] text-[#607782]">STATUS</th></tr></thead><tbody>{items?.slice(0, 6).map((item) => <tr key={item.id} className="table-row border-b border-white/[0.06]"><td className="py-4"><Link href={`/transactions/${item.id}`} className="font-mono text-[10px] text-[#6DE7F2]">{item.id}</Link><div className="mt-1 text-[10px] text-[#718992]">{item.failureReason}</div></td><td className="py-4 font-display text-[13px] text-[#E7F4F7]">{fullMoney(item.amount)}</td><td className="py-4 font-display text-[15px] text-[#81E6A8]">{item.recoveryProbability}%</td><td className="py-4"><ActionLabel action={item.aiAction} /></td><td className="py-4">{item.policy === "approved" ? <StatusPill label="Approved" tone="success" /> : <StatusPill label="Blocked" tone="danger" />}</td><td className="py-4"><StatusLabel status={item.status} /></td></tr>)}</tbody></table>{!items && <LoadingBlock lines={5} />}</div></div><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel>ENGINE GUARDRAILS</SectionLabel><div className="space-y-4">{[["Amount threshold", "₹10,000", true], ["Retry attempts", "2 max", true], ["Confidence floor", "80%", true], ["Human review route", "Active", true]].map(([label, value, good]) => <div key={label as string} className="flex items-center justify-between border-b border-white/[0.07] pb-3"><div><div className="font-mono text-[10px] text-[#9EB3B8]">{label as string}</div><div className="mt-1 font-mono text-[9px] text-[#607782]">{value as string}</div></div>{good ? <Check className="h-4 w-4 text-[#81E6A8]" /> : <X className="h-4 w-4 text-[#FF8C88]" />}</div>)}</div><div className="mt-6 rounded-lg border border-[#F0B36B]/15 bg-[#F0B36B]/[0.04] p-3 font-mono text-[9px] leading-4 text-[#B89A72]"><ShieldAlert className="mr-2 inline h-3.5 w-3.5 text-[#F0B36B]" />Actions above threshold are automatically routed to human review.</div></div></div>{running && <div className="fixed inset-0 z-50 grid place-items-center bg-[#050B10]/90 px-4 backdrop-blur-sm"><div className="glass-panel w-full max-w-2xl rounded-2xl p-6 sm:p-8"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] tracking-[.18em] text-[#6DE7F2]">BATCH RECOVERY / DEMO RUN</div><h3 className="mt-2 font-display text-2xl text-[#F0FBFC]">The engine is processing value, not just rows.</h3><p className="mt-2 text-[12px] text-[#7D969F]">Policy checks are applied before every automated action.</p></div><div className="grid h-11 w-11 place-items-center rounded-full border border-[#6DE7F2]/25 bg-[#6DE7F2]/[0.07]"><RefreshCw className="h-5 w-5 animate-spin text-[#6DE7F2]" /></div></div><div className="mt-8 space-y-3">{stages.map((item, index) => <div key={item} className={cn("flex items-center gap-3 rounded-lg border px-3 py-2.5 font-mono text-[10px] transition", index < stage ? "border-[#81E6A8]/15 bg-[#81E6A8]/[0.04] text-[#81E6A8]" : index === stage ? "border-[#6DE7F2]/30 bg-[#6DE7F2]/[0.07] text-[#6DE7F2]" : "border-white/[0.06] text-[#526C77]")}>{index < stage ? <Check className="h-3.5 w-3.5" /> : index === stage ? <Activity className="h-3.5 w-3.5 animate-pulse" /> : <span className="w-3.5 text-center">0{index + 1}</span>}<span>{item}</span>{index === stage && <span className="ml-auto text-[8px] tracking-[.12em]">IN PROGRESS</span>}</div>)}</div><div className="mt-7 h-1.5 overflow-hidden rounded-full bg-white/[0.07]"><div className="h-full rounded-full bg-gradient-to-r from-[#6DE7F2] to-[#81E6A8] transition-all duration-300" style={{ width: `${Math.max(8, ((stage + 1) / stages.length) * 100)}%` }} /></div></div></div>}{result && <div className="fixed inset-0 z-50 grid place-items-center bg-[#050B10]/90 px-4 backdrop-blur-sm"><div className="glass-panel w-full max-w-2xl rounded-2xl p-6 sm:p-8"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] tracking-[.18em] text-[#81E6A8]">RECOVERY COMPLETE / RUN_0092</div><h3 className="mt-2 font-display text-3xl text-[#F0FBFC]">The ledger moved forward.</h3><p className="mt-2 text-[12px] text-[#7D969F]">The batch finished with policy outcomes and merchant escalations recorded.</p></div><button onClick={() => setResult(null)} className="rounded-lg p-2 text-[#78919B] hover:bg-white/[0.06] hover:text-white"><X className="h-4 w-4" /></button></div><div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["RECOVERED", money(result.recovered), "#81E6A8"], ["RATE", `${result.recoveryRate}%`, "#6DE7F2"], ["AUTOMATED", result.approved.toString(), "#8295FF"], ["ESCALATED", result.escalated.toString(), "#F0B36B"]].map(([label, value, color]) => <div key={label} className="rounded-lg bg-white/[0.04] p-3"><div className="font-mono text-[9px] text-[#607782]">{label}</div><div className="mt-2 font-display text-xl" style={{ color }}>{value}</div></div>)}</div><div className="mt-6 flex flex-wrap gap-3 font-mono text-[9px] text-[#78919B]"><span>{result.riskEvents} risk events detected</span><span>·</span><span>{result.stopped} stopped by policy</span><span>·</span><span>Audit trail updated</span></div><button onClick={() => setResult(null)} className="btn-signal mt-7 w-full rounded-lg bg-[#6DE7F2] px-4 py-3 font-mono text-[10px] font-semibold tracking-[.12em] text-[#061116]">RETURN TO RECOVERY CENTER</button></div></div>}</AppShell>;
}

export function AnalyticsPage() {
  const [data, setData] = useState<AnalyticsSnapshot | null>(null); const [range, setRange] = useState("30D");
  useEffect(() => { getAnalytics().then(setData); }, []);
  return <AppShell title="Analytics Suite" eyebrow="ANALYTICS"><PageIntro eyebrow="PERFORMANCE INTELLIGENCE / EVALUATION" title="See where the engine creates lift." description="Compare recovery performance by failure type, payment method, customer segment, and decision confidence." action={<div className="flex gap-1 rounded-lg border border-white/[0.1] bg-white/[0.025] p-1">{["7D", "30D", "90D"].map((item) => <button key={item} onClick={() => setRange(item)} className={cn("rounded-md px-3 py-1.5 font-mono text-[9px]", range === item ? "bg-white/[0.08] text-[#E7F4F7]" : "text-[#607782]")}>{item}</button>)}</div>} />{data ? <><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel action={<div className="flex gap-4 font-mono text-[9px] text-[#718992]"><span><i className="mr-2 inline-block h-1.5 w-5 rounded bg-[#6DE7F2]" />ReviveAI</span><span><i className="mr-2 inline-block h-1.5 w-5 rounded bg-[#607782]" />Baseline</span></div>}>REVENUE RECOVERY OVER TIME</SectionLabel><RecoveryTrendChart data={data.chart} /></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="glass-panel rounded-xl p-5"><SectionLabel>RECOVERY BY FAILURE TYPE</SectionLabel><FailureMixChart data={data.failureTypes} /></div><div className="glass-panel rounded-xl p-5"><SectionLabel>RECOVERY BY PAYMENT METHOD</SectionLabel><PaymentMethodsChart data={data.paymentMethods} /></div></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><div className="glass-panel rounded-xl p-5"><SectionLabel>RECOVERY PROBABILITY DISTRIBUTION</SectionLabel><ProbabilityChart data={data.probabilityDistribution} /><div className="mt-4 flex items-center justify-between border-t border-white/[0.08] pt-4 font-mono text-[9px] text-[#708891]"><span>Higher confidence</span><span className="text-[#81E6A8]">143 transactions above 80%</span></div></div><div className="glass-panel rounded-xl p-5"><SectionLabel>RECOVERY BY CUSTOMER SEGMENT</SectionLabel><div className="space-y-5 pt-3">{data.segments.map((segment) => <div key={segment.name}><div className="mb-2 flex justify-between font-mono text-[10px]"><span className="text-[#9DB2B7]">{segment.name}</span><span className="text-[#81E6A8]">{segment.value}%</span></div><div className="h-2 overflow-hidden rounded-full bg-white/[0.06]"><div className="h-full rounded-full bg-gradient-to-r from-[#6DE7F2] to-[#81E6A8]" style={{ width: `${segment.value}%` }} /></div></div>)}</div></div></div><div className="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="glass-panel rounded-xl p-5"><SectionLabel>AUTOMATED VS HUMAN ACTIONS</SectionLabel><div className="mt-5 flex items-center gap-6"><div className="relative h-36 w-36 shrink-0 rounded-full" style={{ background: "conic-gradient(#81E6A8 0 76%, #F0B36B 76% 93%, #FF8C88 93% 100%)" }}><div className="absolute inset-3 grid place-items-center rounded-full bg-[#0D1B25]"><div className="text-center"><div className="font-display text-2xl text-[#E7F4F7]">76%</div><div className="font-mono text-[8px] text-[#607782]">AUTOMATED</div></div></div></div><div className="space-y-3 font-mono text-[10px] text-[#91A8AF]"><div><i className="mr-2 inline-block h-2 w-2 rounded-full bg-[#81E6A8]" />Automated · 76%</div><div><i className="mr-2 inline-block h-2 w-2 rounded-full bg-[#F0B36B]" />Human review · 17%</div><div><i className="mr-2 inline-block h-2 w-2 rounded-full bg-[#FF8C88]" />Policy stopped · 7%</div></div></div></div><div className="glass-panel rounded-xl p-5"><SectionLabel>BASELINE VS REVIVEAI</SectionLabel><div className="mt-5 grid gap-5 sm:grid-cols-[.8fr_1.2fr] sm:items-center"><div><div className="font-mono text-[9px] text-[#607782]">RECOVERY IMPROVEMENT</div><div className="mt-2 font-display text-4xl text-[#81E6A8]">+{(((data.revive - data.baseline) / data.baseline) * 100).toFixed(1)}%</div><p className="mt-2 max-w-xs text-[11px] leading-5 text-[#78919B]">ReviveAI recovered {money(data.revive - data.baseline)} more revenue than the baseline strategy.</p></div><div className="space-y-4">{[["WITHOUT REVIVEAI", data.baseline, "#607782"], ["WITH REVIVEAI", data.revive, "#6DE7F2"]].map(([label, value, color]) => <div key={label as string}><div className="mb-2 flex justify-between font-mono text-[9px] text-[#78919B]"><span>{label as string}</span><span style={{ color: color as string }}>{money(value as number)}</span></div><div className="h-3 overflow-hidden rounded-full bg-white/[0.05]"><div className="h-full rounded-full" style={{ width: `${((value as number) / data.revive) * 100}%`, background: color as string }} /></div></div>)}</div></div></div></div></> : <LoadingBlock lines={5} />}</AppShell>;
}

export function AIDecisionsPage() {
  const [items, setItems] = useState<RecoveryDecision[] | null>(null); const [selected, setSelected] = useState<RecoveryDecision | null>(null);
  useEffect(() => { getDecisions().then(setItems); }, []);
  return <AppShell title="AI Recovery Intelligence" eyebrow="AI DECISIONS"><PageIntro eyebrow="STRUCTURED DECISION LOG / SAFE EXPLANATIONS" title="The system recommends. Policy decides." description="Inspect concise, structured signals behind each recommendation without exposing hidden chain-of-thought." /><div className="glass-panel rounded-xl p-5 sm:p-6"><SectionLabel>DECISION FLOW</SectionLabel><div className="grid gap-2 sm:grid-cols-6">{[["01", "Transaction", WalletCards], ["02", "ML prediction", Target], ["03", "AI diagnosis", Sparkles], ["04", "Recovery strategy", GitBranch], ["05", "Policy engine", ShieldAlert], ["06", "Execution", Zap]].map(([number, label, Icon], index) => <div key={label as string} className="relative flex items-center gap-3 rounded-lg border border-white/[0.07] bg-white/[0.02] p-3 sm:block"><div className="flex h-8 w-8 items-center justify-center rounded-md bg-[#6DE7F2]/[0.08] text-[#6DE7F2]"><Icon className="h-4 w-4" /></div><div className="mt-0 sm:mt-3"><div className="font-mono text-[8px] text-[#607782]">{number as string}</div><div className="mt-1 font-mono text-[9px] uppercase tracking-[.06em] text-[#B4C9CE]">{label as string}</div></div>{index < 5 && <ChevronRight className="absolute -right-3 top-1/2 z-10 hidden h-4 w-4 -translate-y-1/2 text-[#536C77] sm:block" />}</div>)}</div></div><div className="mt-5 grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><div className="glass-panel overflow-hidden rounded-xl"><div className="table-scroll overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="border-b border-white/[0.08] bg-white/[0.02]">{["Decision", "Transaction", "Probability", "Diagnosis", "Recommendation", "Confidence", "Policy", "Outcome"].map((head) => <th key={head} className="px-4 py-3.5 font-mono text-[9px] tracking-[.12em] text-[#607782]">{head}</th>)}</tr></thead><tbody>{items?.map((item) => <tr key={item.id} onClick={() => setSelected(item)} className={cn("table-row cursor-pointer border-b border-white/[0.06]", selected?.id === item.id && "bg-[#6DE7F2]/[0.06]")}><td className="px-4 py-4 font-mono text-[10px] text-[#6DE7F2]">{item.id}</td><td className="px-4 py-4 font-mono text-[10px] text-[#A9BEC3]">{item.transactionId}<div className="mt-1 font-display text-[12px] text-[#E7F4F7]">{fullMoney(item.amount)}</div></td><td className="px-4 py-4 font-display text-[15px] text-[#81E6A8]">{item.probability}%</td><td className="max-w-[160px] px-4 py-4 text-[11px] leading-4 text-[#9DB2B7]">{item.diagnosis}</td><td className="px-4 py-4 font-mono text-[10px] text-[#6DE7F2]">{item.recommendation}</td><td className="px-4 py-4 font-display text-[14px] text-[#B7CAD0]">{item.confidence}%</td><td className="px-4 py-4">{item.policy === "approved" ? <StatusPill label="Approved" tone="success" /> : <StatusPill label="Blocked" tone="danger" />}</td><td className="px-4 py-4"><span className="text-[11px] text-[#A9BEC3]">{item.outcome}</span></td></tr>)}</tbody></table>{!items && <div className="p-5"><LoadingBlock lines={4} /></div>}</div></div><div className="glass-panel min-h-[320px] rounded-xl p-5">{selected ? <><div className="mb-5 flex items-start justify-between"><div><div className="font-mono text-[9px] tracking-[.14em] text-[#6DE7F2]">STRUCTURED EXPLANATION</div><div className="mt-2 font-display text-xl text-[#E7F4F7]">{selected.transactionId}</div></div><button onClick={() => setSelected(null)} className="rounded-md p-1.5 text-[#607782] hover:bg-white/[0.06] hover:text-white"><X className="h-4 w-4" /></button></div><div className="rounded-lg border border-[#6DE7F2]/15 bg-[#6DE7F2]/[0.035] p-4"><div className="font-mono text-[9px] text-[#6DE7F2]">WHY THIS ACTION</div><div className="mt-3 space-y-2.5">{selected.reasons.map((reason) => <div key={reason} className="flex gap-2 text-[11px] leading-4 text-[#A6BCC2]"><Check className="mt-0.5 h-3.5 w-3.5 shrink-0 text-[#81E6A8]" />{reason}</div>)}</div></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-lg bg-white/[0.035] p-3"><div className="font-mono text-[9px] text-[#607782]">AI LAYER</div><div className="mt-2 font-mono text-[10px] text-[#6DE7F2]">RECOMMENDED {selected.recommendation}</div></div><div className="rounded-lg bg-white/[0.035] p-3"><div className="font-mono text-[9px] text-[#607782]">POLICY LAYER</div><div className={cn("mt-2 font-mono text-[10px]", selected.policy === "approved" ? "text-[#81E6A8]" : "text-[#FF8C88]")}>{selected.policy === "approved" ? "APPROVED" : "BLOCKED"}</div></div></div></> : <div className="flex h-full flex-col items-center justify-center text-center"><Bot className="mb-4 h-8 w-8 text-[#536C77]" /><div className="font-display text-[15px] text-[#D8E9EB]">Inspect a decision</div><p className="mt-2 max-w-xs text-[11px] leading-5 text-[#6F8791]">Select a row to see the safe, structured explanation behind the recommendation.</p></div>}</div></div></AppShell>;
}

export function AuditPage() {
  const [events, setEvents] = useState<AuditEvent[] | null>(null); const [filter, setFilter] = useState("All events");
  useEffect(() => { getAuditEvents().then(setEvents); }, []);
  const visible = (events || []).filter((event) => filter === "All events" || event.title.toLowerCase().includes(filter.toLowerCase()));
  return <AppShell title="Audit Trail" eyebrow="AUDIT TRAIL" action={<button className="btn-signal hidden items-center gap-2 rounded-lg border border-white/10 bg-white/[0.04] px-3 py-2 font-mono text-[10px] text-[#A9C0C5] sm:flex"><Download className="h-3.5 w-3.5" />EXPORT LOG</button>}><PageIntro eyebrow="IMMUTABLE EVENT STREAM / 7 EVENTS" title="Every decision leaves a trace." description="Chronological evidence of revenue risk, prediction, policy, execution, and recovery events." /><div className="mb-5 flex flex-wrap gap-2">{["All events", "Revenue at risk", "Prediction", "Policy", "Action", "Recovery"].map((option) => <button key={option} onClick={() => setFilter(option)} className={cn("rounded-full border px-3 py-1.5 font-mono text-[9px] tracking-[.08em]", filter === option ? "border-[#6DE7F2]/30 bg-[#6DE7F2]/[0.08] text-[#6DE7F2]" : "border-white/[0.1] bg-white/[0.025] text-[#78919B] hover:text-[#E7F4F7]")}>{option}</button>)}</div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]"><div className="glass-panel rounded-xl p-5 sm:p-7"><SectionLabel action={<span className="font-mono text-[9px] text-[#81E6A8]"><span className="status-dot success mr-2" />LIVE LOG</span>}>CHRONOLOGICAL EVENTS</SectionLabel><div className="relative mt-5 pl-3"><div className="absolute bottom-2 left-[7px] top-2 w-px bg-gradient-to-b from-[#6DE7F2]/40 via-[#6DE7F2]/15 to-transparent" />{events ? visible.map((event, index) => <div key={event.id} className="relative flex gap-5 pb-7 last:pb-0"><div className={cn("relative z-10 mt-1 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-[#0E1A24]", event.status === "success" ? "bg-[#81E6A8]" : event.status === "warning" ? "bg-[#F0B36B]" : event.status === "danger" ? "bg-[#FF8C88]" : "bg-[#6DE7F2]")} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-x-3 gap-y-1"><span className="font-mono text-[10px] text-[#607782]">{event.time}</span><span className={cn("font-mono text-[10px] tracking-[.12em]", event.status === "success" ? "text-[#81E6A8]" : event.status === "warning" ? "text-[#F0B36B]" : event.status === "danger" ? "text-[#FF8C88]" : "text-[#6DE7F2]")}>{event.title}</span><span className="font-mono text-[9px] text-[#536C77]">{event.transactionId}</span></div><div className="mt-2 text-[12px] text-[#C2D5D8]">{event.detail}</div>{event.amount && <div className="mt-1 font-display text-[13px] text-[#E7F4F7]">{fullMoney(event.amount)}</div>}</div><div className="hidden font-mono text-[9px] text-[#536C77] sm:block">#{String(visible.length - index).padStart(3, "0")}</div></div>) : <LoadingBlock lines={5} />}</div></div><div className="space-y-5"><div className="glass-panel rounded-xl p-5"><SectionLabel>SYSTEM STATUS</SectionLabel><div className="space-y-3">{[["AI Agent", "Operational", "success"], ["ML Model", "Operational", "success"], ["Recovery Engine", "Operational", "success"], ["Razorpay", "Test mode", "warning"], ["Database", "Operational", "success"], ["Webhook Listener", "Operational", "success"]].map(([label, value, tone]) => <div key={label} className="flex items-center justify-between border-b border-white/[0.06] pb-3 last:border-0 last:pb-0"><span className="text-[11px] text-[#9DB2B7]">{label}</span><span className={cn("flex items-center gap-2 font-mono text-[9px]", tone === "success" ? "text-[#81E6A8]" : "text-[#F0B36B]")}><span className={cn("status-dot", tone)} />{value}</span></div>)}</div></div><div className="glass-panel rounded-xl p-5"><SectionLabel>EVENT INTEGRITY</SectionLabel><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-lg bg-[#81E6A8]/[0.08] text-[#81E6A8]"><LockKeyhole className="h-5 w-5" /></div><div><div className="font-display text-[14px] text-[#E7F4F7]">All events accounted for</div><div className="mt-1 font-mono text-[9px] text-[#607782]">Hash chain · healthy</div></div></div></div></div></div></AppShell>;
}
